test('FormData parsing tests', async (t) => {
  for (const test of tests) {
    active.set(test, 1)

    const { what, boundary, source } = test

    const body = source.reduce((a, b) => a + b, '')
    const response = new Response(body, {
      headers: {
        'content-type': `multipart/form-data; boundary=${boundary}`
      }
    })

    let fd
    const results = []

    try {
      fd = await response.formData()
    } catch (e) {
      results.push({ error: e.message })

      if (test.expected.length === 1 && test.expected[0].error) {
        active.delete(test)
      }

      continue
    }

    for (const [name, value] of fd) {
      if (typeof value === 'string') { // field
        results.push({
          type: 'field',
          name,
          val: value,
          info: {
            encoding: '7bit',
            mimeType: 'text/plain'
          }
        })
      } else { // File
        results.push({
          type: 'file',
          name,
          data: Buffer.from(await value.arrayBuffer()),
          info: {
            filename: value.name,
            encoding: '7bit',
            mimeType: value.type
          }
        })
      }
    }

    active.delete(test)

    t.assert.deepStrictEqual(
      results,
      test.expected,
      `[${what}] Results mismatch.\n` +
        `Parsed: ${inspect(results)}\n` +
        `Expected: ${inspect(test.expected)}`
    )
  }
})

