test('IncomingMessage', async (t) => {
  t = tspl(t, { plan: 2 })

  const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
    res.end()
  })
  after(() => server.close())

  server.listen(0, () => {
    const proxyClient = new Client(`http://localhost:${server.address().port}`)
    after(() => proxyClient.destroy())

    const proxy = createServer({ joinDuplicateHeaders: true }, (req, res) => {
      proxyClient.request({
        path: '/',
        method: 'PUT',
        body: req
      }, (err, data) => {
        t.ifError(err)
        data.body.pipe(res)
      })
    })
    after(() => proxy.close())

    proxy.listen(0, () => {
      const client = new Client(`http://localhost:${proxy.address().port}`)
      after(() => client.destroy())

      client.request({
        path: '/',
        method: 'PUT',
        body: 'hello world'
      }, (err, data) => {
        t.ifError(err)
      })
    })
  })

  await t.completed
})

test('stream body without destroy', async (t) => {
  t = tspl(t, { plan: 2 })

  const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
    res.end()
  })
  after(() => server.close())
  server.listen(0, () => {
    const client = new Client(`http://localhost:${server.address().port}`)
    after(() => client.destroy())

    const signal = new EE()
    const body = new Readable({ read () {} })
    body.destroy = undefined
    body.on('error', (err) => {
      t.ok(err)
    })
    client.request({
      path: '/',
      method: 'PUT',
      signal,
      body
    }, (err, data) => {
      t.ok(err)
    })
    signal.emit('abort')
  })

  await t.completed
})

test('socket back-pressure', async (t) => {
  t = tspl(t, { plan: 3 })

  const server = createServer({ joinDuplicateHeaders: true })
  let bytesWritten = 0

  const buf = Buffer.allocUnsafe(16384)
  const src = new Readable({
    read () {
      bytesWritten += buf.length
      this.push(buf)
      if (bytesWritten >= 1e6) {
        this.push(null)
      }
    }
  })

  server.on('request', (req, res) => {
    src.pipe(res)
  })
  after(() => server.close())

  server.listen(0)

  await once(server, 'listening')
  const client = new Client(`http://localhost:${server.address().port}`, {
    pipelining: 1
  })
  after(() => client.close())

  client.request({ path: '/', method: 'GET', opaque: 'asd' }, (err, data) => {
    t.ifError(err)
    data.body
      .resume()
      .once('data', () => {
        data.body.pause()
        // TODO: Try to avoid timeout.
        setTimeout(() => {
          t.ok(data.body._readableState.length < bytesWritten - data.body._readableState.highWaterMark)
          src.push(null)
          data.body.resume()
        }, 1e3)
      })
      .on('end', () => {
        t.ok(true, 'pass')
      })
  })
  await t.completed
})

