      t.strictEqual(
        response.headers['content-type'],
        'text/plain; charset=utf-8'
      )
      t.strictEqual(response.headers['x-custom-h2'], 'hello')
      t.strictEqual(response.statusCode, 200)
    }
  )

  client.request(
    {
      path: '/2',
      method: 'GET',
      headers: {
        'x-my-header': 'foo'
      },
      signal
    },
    (err, response) => {
      t.strictEqual(err.name, 'TimeoutError')
    }
  )

  client.request(
    {
      path: '/3',
      method: 'GET',
      headers: {
        'x-my-header': 'foo'
      }
    },
    (err, response) => {
      t.ifError(err)
      t.strictEqual(
        response.headers['content-type'],
        'text/plain; charset=utf-8'
      )
      t.strictEqual(response.headers['x-custom-h2'], 'hello')
      t.strictEqual(response.statusCode, 200)
    }
  )

  client.request(
    {
      path: '/4',
      method: 'GET',
      headers: {
        'x-my-header': 'foo'
      },
      signal
    },
    (err, response) => {
      t.strictEqual(err.name, 'TimeoutError')
    }
  )

  await t.completed
})

test(`do not kill req socket ${bodyType}`, async (t) => {
    t = tspl(t, { plan: 3 })

    const server1 = createServer({ joinDuplicateHeaders: true }, (req, res) => {
      const client = new undici.Client(`http://localhost:${server2.address().port}`)
      after(() => client.close())
      client.request({
        path: '/',
        method: 'POST',
        body: req
      }, (err, response) => {
        t.ifError(err)
        setTimeout(() => {
          response.body.on('data', buf => {
            res.write(buf)
            setTimeout(() => {
              res.end()
            }, 100)
          })
        }, 100)
      })
    })
    after(() => server1.close())

    const server2 = createServer({ joinDuplicateHeaders: true }, (req, res) => {
      setTimeout(() => {
        req.pipe(res)
      }, 100)
    })
    after(() => server2.close())

    server1.listen(0, () => {
      const client = new undici.Client(`http://localhost:${server1.address().port}`)
      after(() => client.close())

      const r = new Readable({ read () {} })
      r.push('hello')
      client.request({
        path: '/',
        method: 'POST',
        body: maybeWrapStream(r, bodyType)
      }, (err, response) => {
        t.ifError(err)
        const bufs = []
        response.body.on('data', (buf) => {
          bufs.push(buf)
          r.push(null)
        })
        response.body.on('end', () => {
          t.strictEqual('hello', Buffer.concat(bufs).toString('utf8'))
        })
      })
    })

    server2.listen(0)

    await t.completed
  })

