test('idempotent retry', async (t) => {
  t = tspl(t, { plan: 11 })

  const body = 'world'
  const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
    let buf = ''
    req.on('data', data => {
      buf += data
    }).on('end', () => {
      t.strictEqual(buf, body)
      res.end()
    })
  })
  after(() => server.close())

  server.listen(0, () => {
    const client = new Client(`http://localhost:${server.address().port}`, {
      pipelining: 2
    })
    after(() => client.close())

    const _err = new Error()

    for (let n = 0; n < 4; ++n) {
      client.stream({
        path: '/',
        method: 'PUT',
        idempotent: true,
        blocking: false,
        body
      }, () => {
        throw _err
      }, (err) => {
        t.strictEqual(err, _err)
      })
    }
  })

  await t.completed
})

test('override HEAD reset', async (t) => {
  t = tspl(t, { plan: 4 })

  const expected = 'testing123'
  const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
    if (req.method === 'GET') {
      res.write(expected)
    }
    res.end()
  }).listen(0)

  after(() => server.close())

  await once(server, 'listening')
  const client = new Client(`http://localhost:${server.address().port}`)
  after(() => client.close())

  let done
  client.on('disconnect', () => {
    if (!done) {
      t.fail()
    }
  })

  client.request({
    path: '/',
    method: 'HEAD',
    reset: false
  }, (err, res) => {
    t.ifError(err)
    res.body.resume()
  })

  client.request({
    path: '/',
    method: 'HEAD',
    reset: false
  }, (err, res) => {
    t.ifError(err)
    res.body.resume()
  })

  client.request({
    path: '/',
    method: 'GET',
    reset: false
  }, (err, res) => {
    t.ifError(err)
    let str = ''
    res.body.on('data', (data) => {
      str += data
    }).on('end', () => {
      t.strictEqual(str, expected)
      done = true
      t.end()
    })
  })

  await t.completed
})

