test('immutable guard', (t) => {
  const headers = new Headers()
  headers.set('key', 'val')
  setHeadersGuard(headers, 'immutable')

  t.assert.throws(() => {
    headers.set('asd', 'asd')
  })
  t.assert.throws(() => {
    headers.append('asd', 'asd')
  })
  t.assert.throws(() => {
    headers.delete('asd')
  })
  t.assert.strictEqual(headers.get('key'), 'val')
  t.assert.strictEqual(headers.has('key'), true)
})

