test('arg validation', (t) => {
  const form = new FormData()

  // constructor
  t.assert.throws(() => {
    // eslint-disable-next-line
    new FormData('asd')
  }, TypeError)

  // append
  t.assert.throws(() => {
    FormData.prototype.append.call(null)
  }, TypeError)
  t.assert.throws(() => {
    form.append()
  }, TypeError)
  t.assert.throws(() => {
    form.append('k', 'not usv', '')
  }, TypeError)

  // delete
  t.assert.throws(() => {
    FormData.prototype.delete.call(null)
  }, TypeError)
  t.assert.throws(() => {
    form.delete()
  }, TypeError)

  // get
  t.assert.throws(() => {
    FormData.prototype.get.call(null)
  }, TypeError)
  t.assert.throws(() => {
    form.get()
  }, TypeError)

  // getAll
  t.assert.throws(() => {
    FormData.prototype.getAll.call(null)
  }, TypeError)
  t.assert.throws(() => {
    form.getAll()
  }, TypeError)

  // has
  t.assert.throws(() => {
    FormData.prototype.has.call(null)
  }, TypeError)
  t.assert.throws(() => {
    form.has()
  }, TypeError)

  // set
  t.assert.throws(() => {
    FormData.prototype.set.call(null)
  }, TypeError)
  t.assert.throws(() => {
    form.set('k')
  }, TypeError)
  t.assert.throws(() => {
    form.set('k', 'not usv', '')
  }, TypeError)

  // iterator
  t.assert.throws(() => {
    Reflect.apply(FormData.prototype[Symbol.iterator], null)
  }, TypeError)

  // toStringTag
  t.assert.doesNotThrow(() => {
    FormData.prototype[Symbol.toStringTag].charAt(0)
  })
})

