  t.plan(1)
  const domain = 'https://domain.com/#a#b'
  const url = new URL(domain)
  const serialized = URLSerializer(url, true)
  t.assert.strictEqual(serialized, url.href.substring(0, url.href.length - url.hash.length))
})

