    t.assert.strictEqual(normalizeOrigin(url1), 'http://example.com')

    const url2 = new URL('https://Api.Example.com:8080/api/v1')
    t.assert.strictEqual(normalizeOrigin(url2), 'https://api.example.com:8080')
  })

