  })
  t.assert.strictEqual(statusCode, 200)
  t.assert.deepStrictEqual(headers, {
    foo: 'bar',
    hello: 'there'
  })

  const response = await getResponse(body)
  t.assert.strictEqual(response, 'foo')
})

