test('calling close twice will only trigger the close event once', async (t) => {
    t = tspl(t, { plan: 1 })

    const server = new WebSocketServer({ port: 0 })

    after(() => server.close())

    server.on('connection', (ws) => {
      ws.on('close', (code) => {
        t.strictEqual(code, 1000)
      })
    })

    const ws = new WebSocket(`ws://localhost:${server.address().port}`)
    ws.addEventListener('open', () => {
      ws.close(1000)
      ws.close(1000)
    })

    await t.completed
  })

test('ByteString', (t) => {
  const name = Symbol('')
  const value = Symbol('')

  for (const method of [
    'get',
    'set',
    'delete',
    'append',
    'has'
  ]) {
    assert.throws(
      () => new Headers()[method](name, value),
      new TypeError(`Headers.${method}: name is a symbol, which cannot be converted to a ByteString.`)
