      type = blob.type
      return fetch(url, {
        method: 'POST',
        body: blob
      })
    }).then(res => res.json()).then(({ body, headers }) => {
      assert.strictEqual(body, 'world')
      assert.strictEqual(headers['content-type'], type)
      assert.strictEqual(headers['content-length'], String(length))
    })
  })

