      await client.close()
    })

    await once(server, 'listening')

    // Send concurrent requests with different skip headers
    const [res1, res2, res3] = await Promise.all([
      client.request({
        origin: 'localhost',
        method: 'GET',
        path: '/',
        headers: { 'x-skip-1': 'true' }
      }),
      client.request({
