test('getSetCookies', { skip: !globalThis.Headers }, () => {
    const headers = new globalThis.Headers({
      'set-cookie': 'undici=getSetCookies; Secure'
    })

    const supportsCookies = headers.getSetCookie()

    if (!supportsCookies) {
      assert.deepEqual(getSetCookies(headers), [])
    } else {
      assert.deepEqual(getSetCookies(headers), [
        {
          name: 'undici',
          value: 'getSetCookies',
          secure: true
        }
      ])
    }
  })

